package main

import (
	"fmt"
	"os"
	"runtime"
	"strings"
	"sync"
	"time"
)

func main() {
	const n = 100_000
	var antes, durante runtime.MemStats
	runtime.ReadMemStats(&antes)

	var wg sync.WaitGroup
	parar := make(chan struct{})
	inicio := time.Now()
	for i := 0; i < n; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			<-parar // espera, sin hacer nada
		}()
	}
	creacion := time.Since(inicio)
	time.Sleep(200 * time.Millisecond)
	runtime.ReadMemStats(&durante)

	fmt.Printf("goroutines vivas: %d\n", runtime.NumGoroutine())
	fmt.Printf("crear %d goroutines: %d ms\n", n, creacion.Milliseconds())
	fmt.Printf("memoria de pilas: %d MB en total, unos %d bytes por goroutine\n",
		(durante.StackInuse-antes.StackInuse)/1_000_000,
		(durante.StackInuse-antes.StackInuse)/n)
	estado, _ := os.ReadFile("/proc/self/status")
	for _, linea := range strings.Split(string(estado), "\n") {
		if strings.HasPrefix(linea, "Threads:") {
			fmt.Println("hilos del sistema operativo:", strings.TrimSpace(strings.TrimPrefix(linea, "Threads:")))
		}
	}
	close(parar)
	wg.Wait()
}

package main

import (
	"fmt"
	"sort"
	"sync"
	"time"
)

type Pedido struct {
	ID    int
	Kilos float64
}

type Resultado struct {
	Pedido     int
	Repartidor int
}

// Cada repartidor es una goroutine: toma pedidos del canal hasta que se cierra.
func repartidor(n int, pedidos <-chan Pedido, hechos chan<- Resultado, wg *sync.WaitGroup) {
	defer wg.Done()
	for p := range pedidos {
		demora := 100 * time.Millisecond
		if p.ID == 3 {
			demora = 500 * time.Millisecond // un pedido complicado
		}
		time.Sleep(demora) // simula el tiempo de entrega
		hechos <- Resultado{p.ID, n}
	}
}

func main() {
	pedidos := make(chan Pedido)
	hechos := make(chan Resultado, 20)
	var wg sync.WaitGroup

	inicio := time.Now()
	for n := 1; n <= 4; n++ {
		wg.Add(1)
		go repartidor(n, pedidos, hechos, &wg)
	}
	for i := 1; i <= 20; i++ {
		pedidos <- Pedido{ID: i, Kilos: 5}
	}
	close(pedidos) // no hay más pedidos: los repartidores terminan solos
	wg.Wait()
	close(hechos)

	porRepartidor := map[int][]int{}
	for r := range hechos {
		porRepartidor[r.Repartidor] = append(porRepartidor[r.Repartidor], r.Pedido)
	}
	for n := 1; n <= 4; n++ {
		sort.Ints(porRepartidor[n])
		fmt.Printf("repartidor %d entregó %d pedidos\n", n, len(porRepartidor[n]))
	}
	fmt.Printf("20 pedidos con 4 repartidores: %d ms (en fila serían 2400)\n",
		time.Since(inicio).Milliseconds())
}

// Lo mismo que el programa de Go, pero con async/await de JavaScript:
// 4 «repartidores» sacan pedidos de una misma cola hasta que se vacía.
const espera = (ms) => new Promise((ok) => setTimeout(ok, ms));

const cola = Array.from({ length: 20 }, (_, i) => i + 1);   // pedidos 1..20
const entregados = { 1: 0, 2: 0, 3: 0, 4: 0 };

async function repartidor(n) {
  while (cola.length > 0) {
    const pedido = cola.shift();                 // saco el próximo de la fila
    await espera(pedido === 3 ? 500 : 100);      // el pedido 3 es complicado
    entregados[n]++;
  }
}

const inicio = Date.now();
await Promise.all([1, 2, 3, 4].map(repartidor));
for (const n of [1, 2, 3, 4]) console.log(`repartidor ${n} entregó ${entregados[n]} pedidos`);
console.log(`total: ${Date.now() - inicio} ms (en fila serían 2400)`);

package main

import (
	"fmt"
	"sync"
)

func main() {
	stock := 0
	var wg sync.WaitGroup
	for i := 0; i < 1000; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			stock++ // mil goroutines tocan la misma variable sin coordinarse
		}()
	}
	wg.Wait()
	fmt.Println("stock final:", stock, "(esperado: 1000)")
}

package main

import (
	"fmt"
	"sync"
)

func main() {
	movimientos := make(chan int)
	listo := make(chan int)

	// Una sola goroutine es dueña del stock: nadie más lo toca.
	go func() {
		stock := 0
		for m := range movimientos {
			stock += m
		}
		listo <- stock
	}()

	var wg sync.WaitGroup
	for i := 0; i < 1000; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			movimientos <- 1 // en vez de tocar la variable, mandan un mensaje
		}()
	}
	wg.Wait()
	close(movimientos)
	fmt.Println("stock final:", <-listo)
}

