package main

import (
	"fmt"
	"runtime"
	"runtime/debug"
	"time"
)

var (
	sumidero []byte // obliga a que la basura viva en el heap
	raiz     *Envio // mantiene vivos los envíos hasta el final
)

type Envio struct {
	ID      int
	Destino string
	Kilos   float64
	Next    *Envio
}

func main() {
	// Heap vivo grande: 2 millones de envíos enlazados (el recolector tiene que recorrerlos).
	for i := 0; i < 2_000_000; i++ {
		raiz = &Envio{ID: i, Destino: "Palermo", Kilos: 1.5, Next: raiz}
	}

	// Mientras tanto, el programa sigue trabajando y generando basura.
	inicio := time.Now()
	var peorDemora time.Duration
	for time.Since(inicio) < 3*time.Second {
		t := time.Now()
		sumidero = make([]byte, 256<<10) // 256 KB de basura por vuelta
		if d := time.Since(t); d > peorDemora {
			peorDemora = d
		}
	}

	var s debug.GCStats
	debug.ReadGCStats(&s)
	var maxPausa time.Duration
	for _, p := range s.Pause {
		if p > maxPausa {
			maxPausa = p
		}
	}
	var m runtime.MemStats
	runtime.ReadMemStats(&m)
	fmt.Printf("heap en uso al final: ~%d MB · ciclos de GC: %d\n", m.HeapAlloc>>20, s.NumGC)
	fmt.Printf("pausa más larga del recolector: %v · pausa total: %v\n", maxPausa, s.PauseTotal)
	fmt.Printf("la vuelta más lenta del programa: %v\n", peorDemora)
	runtime.KeepAlive(raiz)
}
